    "thirdPartyUses": [
      {
        "vendor": "Google",
        "description": "Google Analytics is used to track user behavior and improve the service."
      },
      {
        "vendor": "Facebook",
        "description": "Facebook Pixel is used for advertising purposes."
      }
    ]
  },
  "dataProtection": {
    "securityMeasures": [
      {
        "type": "Encryption",
        "description": "Personal data is encrypted both in transit and at rest to protect against unauthorized access."
      },
      {
        "type": "Access Controls",
        "description": "We implement strict access controls to ensure that only authorized personnel can access your personal information."
      }
    ],
    "retentionPolicies": [
      {
        "type": "Data Retention",
        "description": "We retain data for as long as necessary to fulfill the purposes outlined in this Privacy Policy, or as required by law. Data will be deleted upon request if no longer needed."
      },
      {
        "type": "Anonymization",
        "description": "Personal data is anonymized where possible to protect user privacy."
      }
    ]
  },
  "userRights": {
    "accessRequests": [
