  "consent": {
    "id": "123",
    "status": "active",
    "date": "2023-10-05T14:30:00Z"
  },
  "purposes": [
    {
      "name": "Advertising",
      "description": "Advertisements presented to you on this service can be based on your advertising profiles, which can reflect your activity on this or other websites or apps (like the forms you submit, content you look at), possible interests and personal aspects.",
      "vendors": ["6sense", "ADYOULIKE (OpenWeb)", "ADventori", "Active Agent (Virtual Minds)", "AcuityAds", "AdElement Media Solutions", "Adara (Rate Gain)", "Adex (Virtual Minds)", "Adform", "Adition (Virtual Minds)"]
    },
    {
      "name": "Create profiles to personalise content",
      "description": "Information about your activity on this service can be stored and combined with other information about you or similar users. This is used to build or improve a profile about you, which might include possible interests and personal aspects.",
      "vendors": ["Adex (Virtual Minds)", "Adsquare", "Appier", "BeOp", "Bmind (Jakala)", "Commanders Act", "Dentsu", "Dianomi", "Easymedia"]
    },
    {
      "name": "Use profiles to select personalised content",
      "description": "Content presented on this service can be based on your personalisation profiles, which reflect your activity and possible interests. This is used to adapt the order of content shown.",
      "vendors": ["Adex (Virtual Minds)", "Adsquare", "Appier", "BeOp", "Bmind (Jakala)", "Brand Metrics", "Commanders Act", "Dentsu", "Dianomi", "Easymedia"]
    },
    {
      "name": "Measure advertising performance",
      "description": "Information about which ads are presented and how users interact with them is used to measure the effectiveness of ad campaigns.",
      "vendors": ["6sense", "ABCS INSIGHTS", "ADYOULIKE (OpenWeb)", "ADventori", "Active Agent (Virtual Minds)", "AcuityAds", "AdElement Media Solutions", "Adara (Rate Gain)", "Adelaide", "Adex (Virtual Minds)"]
    },
    {
      "name": "Measure content performance",
      "description": "Information about which content is presented and how users interact with it helps determine the relevance of non-advertising content.",
      "vendors": ["6sense", "AcuityAds", "Adelaide", "Adex (Virtual Minds)", "Adsquare", "Aniview", "Arrivalist (AirDNA)", "Artefact Deutschland GmbH", "AudienceProject", "BeOp"]
    }
  ]
}

{
  "privacyPolicy": {
    "title": "Privacy Policy",
    "description": "This Privacy Policy explains how we collect, use, and protect your personal information when you interact with our services."
  },
  "dataCollection": {
    "title": "Data Collection",
    "description": "We may collect various types of data from you, including but not limited to: (1) Personal Information such as name, email address, phone number; (2) Usage Data which includes information about how you use our services and interact with content on the platform."
  },
  "dataUse": {
    "title": "Data Use",
    "description": "We may use your data for various purposes including: (1) Providing Services - to provide, maintain, and improve our services; (2) Personalization - to personalize your experience by showing you content that is more relevant to your interests;"
  },
  "dataProtection": {
    "title": "Data Protection",
    "description": "We take reasonable measures to protect the security of your personal information. This includes using encryption, access controls, and other security technologies."
  },
  "thirdPartyServices": {
    "title": "Third-Party Services",
    "description": "Our services may include links or references to third-party websites or services. We are not responsible for the privacy practices or content of these third parties."
  },
  "userControl": {
    "title": "User Control",
    "description": "You have control over your personal information and can choose whether you want to share it with us by adjusting settings in our app or website."
  }
}

