{
  "title": "OpenStax",
  "description": "OpenStax is the world’s largest publisher of open education resources (OER) and a provider of interactive learning technologies and education research for high school and college. We are a nonprofit initiative of Rice University.",
  "mission": "To make an amazing education accessible for all.",
  "key_features": [
    {
      "title": "25 years of making a difference",
      "description": "Since the publication of our first textbook in 2012, we have saved 36.1 million students $2.9 billion across 150 countries."
    },
    {
      "title": "Auto-graded assessments and LMS grade sync",
      "description": "Assign readings, interactives, and assessments directly in your LMS with OpenStax Assignable, our official teaching and learning platform."
    },
    {
      "title": "Teach freely, learn equitably",
      "description": "Knowledge is a public good, not a privilege. OpenStax values inclusivity, representation, and the democratization of knowledge."
    },
    {
      "title": "Educating the world requires partnership",
      "description": "OpenStax partners with EdTech organizations to deliver low-cost, high-value instructional tools aligned with our content."
    }
  ],
  "sections": [
    {
      "title": "Higher Education",
      "description": "We publish high-quality, peer-reviewed, openly licensed college textbooks that are free online and low-cost in print.",
      "cta": "Find your subject"
    },
    {
      "title": "K12 Education",
      "description": "Explore our openly licensed library of resources and free instructional materials for high school teachers.",
      "cta": "Explore K12 Free Resources"
    },
    {
      "title": "Learning Research",
      "description": "Get personalized learning insights and earn recognition badges. OpenStax Kinetic is a platform to help understand learning.",
      "cta": "Try OpenStax Kinetic"
    }
  ],
  "news": [
    {
      "title": "Imagine... no limits to learning!",
      "description": "OpenStax is looking to the future with excitement and purpose. Our team is creating tools and technologies that can help every learner achieve their dreams.",
      "cta": "Watch the video"
    },
    {
      "title": "Full computer science collection now available!",
      "description": "This collection includes 5 up-to-date, relevant, and expertly authored digital textbooks, each with free aligned instructional support materials.",
      "cta": "Read the press release"
    },
    {
      "title": "OpenStax Algebra 1 approved by Texas SBOE!",
      "description": "Developed in collaboration with more than 250 Texas teachers, this engaging, research-based curriculum has officially been added to the Texas Instructional Materials Allotment list.",
      "cta": "Read the press release"
    },
    {
      "title": "Start the school year with OpenStax!",
      "description": "Explore top digital resources, tools, and tips for back to school, all in one place. Check out our back-to-school hub for free textbooks, classroom support, and student-ready materials!",
      "cta": "Explore the back-to-school hub"
    }
  ],
  "footer": {
    "mission_statement": "OpenStax’s mission is to make an amazing education accessible for all.",
    "nonprofit_status": "OpenStax is part of Rice University, which is a 501(c)(3) nonprofit. Give today and help us reach more students."
  }
}

